create table app.location_schedule(id uuid primary key default gen_random_uuid(),org_id uuid not null references app.organization(id) on delete cascade,location_id uuid not null,timezone text not null default 'Asia/Kuala_Lumpur',weekdays jsonb not null default '[[],[],[],[],[],[],[]]',closures jsonb not null default '[]',revision int not null default 1,unique(org_id,location_id),unique(org_id,id),foreign key(org_id,location_id)references app.location(org_id,id) on delete cascade);
create table app.knowledge_item(id uuid primary key default gen_random_uuid(),org_id uuid not null references app.organization(id) on delete cascade,agent_id uuid not null,kind text not null check(kind in('faq','services','text-document')),name text not null,content text not null check(octet_length(content)<=100000),revision int not null default 1,created_at timestamptz not null default now(),unique(org_id,id),foreign key(org_id,agent_id)references app.agent(org_id,id)on delete cascade);
create table app.agent_version(id uuid primary key default gen_random_uuid(),org_id uuid not null references app.organization(id)on delete cascade,agent_id uuid not null,sequence int not null,snapshot jsonb not null,actor_id uuid not null,created_at timestamptz not null default now(),unique(org_id,id),unique(org_id,agent_id,id),unique(org_id,agent_id,sequence),foreign key(org_id,agent_id)references app.agent(org_id,id)on delete cascade);
alter table app.agent add constraint published_version_own_agent foreign key(org_id,id,published_version_id) references app.agent_version(org_id,agent_id,id) deferrable initially deferred;
grant select,insert,update on app.location_schedule,app.knowledge_item to jomcall_app;grant delete on app.knowledge_item to jomcall_app;grant select,insert on app.agent_version to jomcall_app;
grant select on app.agent,app.agent_version to jomcall_authz;grant create on schema app_private to jomcall_authz;
create function app_private.published_version(p_agent uuid)returns uuid language sql stable security definer set search_path='' as $$select published_version_id from app.agent where id=p_agent and org_id=nullif(current_setting('app.org_id',true),'')::uuid and app_private.active_role(org_id)is not null$$;
create function app_private.agent_summary(p_org uuid)returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('id',id,'revision',revision,'published_version_id',published_version_id)from app.agent where org_id=p_org and app_private.active_role(p_org)is not null order by created_at,id limit 1$$;
alter function app_private.published_version(uuid)owner to jomcall_authz;alter function app_private.agent_summary(uuid)owner to jomcall_authz;
revoke all on function app_private.published_version(uuid),app_private.agent_summary(uuid)from public;
grant execute on function app_private.published_version(uuid),app_private.agent_summary(uuid)to jomcall_app;
revoke create on schema app_private from jomcall_authz;
do $$ declare t text;begin foreach t in array array['location_schedule','knowledge_item','agent_version']loop
 execute format('alter table app.%I enable row level security',t);execute format('alter table app.%I force row level security',t);
 execute format('create policy tenant_read on app.%I for select to jomcall_app using(org_id=nullif(current_setting(''app.org_id'',true),'''')::uuid and app_private.active_role(org_id)in(''owner'',''admin''))',t);
 execute format('create policy manager_insert on app.%I for insert to jomcall_app with check(org_id=nullif(current_setting(''app.org_id'',true),'''')::uuid and app_private.active_role(org_id)in(''owner'',''admin''))',t);
 if t<>'agent_version'then execute format('create policy manager_update on app.%I for update to jomcall_app using(org_id=nullif(current_setting(''app.org_id'',true),'''')::uuid and app_private.active_role(org_id)in(''owner'',''admin''))with check(org_id=nullif(current_setting(''app.org_id'',true),'''')::uuid and app_private.active_role(org_id)in(''owner'',''admin''))',t);end if;
 end loop;end $$;
create policy manager_delete on app.knowledge_item for delete to jomcall_app using(org_id=nullif(current_setting('app.org_id',true),'')::uuid and app_private.active_role(org_id)in('owner','admin'));
create policy staff_schedule on app.location_schedule for select to jomcall_app using(org_id=nullif(current_setting('app.org_id',true),'')::uuid and app_private.active_role(org_id)is not null);
create policy published_read on app.agent_version for select to jomcall_app using(org_id=nullif(current_setting('app.org_id',true),'')::uuid and id=app_private.published_version(agent_id));
create index knowledge_agent on app.knowledge_item(org_id,agent_id);
